import requests
import random
import re
import string
from config import SHORT_URL, SHORT_API, MESSAGES
from pyrogram import Client, filters
from pyrogram.types import Message, InlineKeyboardMarkup, InlineKeyboardButton, CallbackQuery, InputMediaPhoto
from pyrogram.errors.pyromod import ListenerTimeout
from helper.helper_func import force_sub

# ✅ In-memory cache — keyed by (active shortner name, url) so switching shortners
# never serves a link generated by a different provider.
shortened_urls_cache = {}

NAME_RE = re.compile(r'^[A-Za-z0-9_\-]{1,20}$')

def generate_random_alphanumeric():
    characters = string.ascii_letters + string.digits
    return ''.join(random.choice(characters) for _ in range(8))

#===============================================================#
# Helpers — multi-shortner support
#===============================================================#

def get_active_shortener(client):
    """Return the config dict {url, api, tutorial_link} of the currently active shortner, or None."""
    shorteners = getattr(client, 'shorteners', {}) or {}
    active = getattr(client, 'active_shortener', None)
    if active and active in shorteners:
        return shorteners[active]
    return None

async def save_shorteners(client):
    """Persist client.shorteners + client.active_shortener to the DB and refresh the legacy mirror attrs."""
    await client.mongodb.update_shortner_setting('shorteners', client.shorteners, client.bot_id)
    await client.mongodb.update_shortner_setting('active', client.active_shortener, client.bot_id)
    sync_mirror(client)

def sync_mirror(client):
    """Keep client.short_url/short_api/tutorial_link mirroring the active shortner (used by settings.py etc.)."""
    active_cfg = get_active_shortener(client) or {}
    client.short_url = active_cfg.get('url', SHORT_URL)
    client.short_api = active_cfg.get('api', SHORT_API)
    client.tutorial_link = active_cfg.get('tutorial_link', "")

#===============================================================#

def _shorten_with_config(url, cfg, cache_key):
    """Shared shortening logic — takes an explicit {url, api, ...} config
    rather than reading it off the client, so it works for both the regular
    active shortner and the auto-mode cycle."""
    if cache_key in shortened_urls_cache:
        return shortened_urls_cache[cache_key]

    try:
        alias = generate_random_alphanumeric()
        short_url = cfg.get('url', SHORT_URL)
        short_api = cfg.get('api', SHORT_API)

        api_url = f"https://{short_url}/api?api={short_api}&url={url}&alias={alias}"
        response = requests.get(api_url)
        rjson = response.json()

        if rjson.get("status") == "success" and response.status_code == 200:
            short_link = rjson.get("shortenedUrl", url)
            shortened_urls_cache[cache_key] = short_link
            return short_link
    except Exception as e:
        print(f"[Shortener Error] {e}")

    return None  # fallback — caller should deliver file directly

def get_short(url, client):

    # Check if shortner is enabled
    shortner_enabled = getattr(client, 'shortner_enabled', True)
    if not shortner_enabled:
        return None  # shortner disabled — caller will deliver file directly

    active_name = getattr(client, 'active_shortener', None)
    active_cfg = get_active_shortener(client)
    if not active_cfg:
        return None  # no shortner configured — caller will deliver file directly

    cache_key = f"{active_name}:{url}"
    return _shorten_with_config(url, active_cfg, cache_key)

#===============================================================#
# Auto-mode shortner support
#===============================================================#

def get_auto_shorteners(client):
    """Return this bot's ordered list of auto-mode shortner configs."""
    return getattr(client, 'auto_shorteners', []) or []

def get_auto_short(url, cfg, index):
    """Shorten `url` using the auto-mode shortner at position `index` (for cache keying only)."""
    cache_key = f"auto:{index}:{cfg.get('url', '')}:{url}"
    return _shorten_with_config(url, cfg, cache_key)

