async def shortner_panel(client, query_or_message):
    shorteners = getattr(client, 'shorteners', {}) or {}
    active_name = getattr(client, 'active_shortener', None)
    active_cfg = get_active_shortener(client)
    shortner_enabled = getattr(client, 'shortner_enabled', True)

    # Check if the active shortner is working (only if enabled + configured)
    if shortner_enabled and active_cfg:
        try:
            test_response = requests.get(
                f"https://{active_cfg.get('url', SHORT_URL)}/api?api={active_cfg.get('api', SHORT_API)}&url=https://google.com&alias=test",
                timeout=5
            )
            status = "✓ ᴡᴏʀᴋɪɴɢ" if test_response.status_code == 200 else "✗ ɴᴏᴛ ᴡᴏʀᴋɪɴɢ"
        except:
            status = "✗ ɴᴏᴛ ᴡᴏʀᴋɪɴɢ"
    elif not active_cfg:
        status = "✗ ɴᴏɴᴇ ᴄᴏɴꜰɪɢᴜʀᴇᴅ"
    else:
        status = "✗ ᴅɪsᴀʙʟᴇᴅ"

    enabled_text = "✓ ᴇɴᴀʙʟᴇᴅ" if shortner_enabled else "✗ ᴅɪsᴀʙʟᴇᴅ"
    toggle_text = "✗ ᴏғғ" if shortner_enabled else "✓ ᴏɴ"

    if shorteners:
        list_lines = []
        for name in shorteners:
            marker = "✓" if name == active_name else "•"
            list_lines.append(f"{marker} `{name}` — `{shorteners[name].get('url', '?')}`")
        shorteners_display = "\n".join(list_lines)
    else:
        shorteners_display = "_ɴᴏ ꜱʜᴏʀᴛɴᴇʀꜱ ᴀᴅᴅᴇᴅ ʏᴇᴛ_"

    active_url = active_cfg.get('url', 'ɴᴏᴛ ꜱᴇᴛ') if active_cfg else 'ɴᴏᴛ ꜱᴇᴛ'
    active_api = active_cfg.get('api', '') if active_cfg else ''
    active_tut = active_cfg.get('tutorial_link', 'ɴᴏᴛ ꜱᴇᴛ') if active_cfg else 'ɴᴏᴛ ꜱᴇᴛ'

    msg = f"""<blockquote>✦ 𝗦𝗛𝗢𝗥𝗧𝗡𝗘𝗥 𝗦𝗘𝗧𝗧𝗜𝗡𝗚𝗦</blockquote>
**<u>ᴀᴄᴛɪᴠᴇ ꜱʜᴏʀᴛɴᴇʀ:</u>**
<blockquote>›› **ꜱᴛᴀᴛᴜꜱ:** {enabled_text}
›› **ɴᴀᴍᴇ:** `{active_name or 'ɴᴏɴᴇ'}`
›› **ᴜʀʟ:** `{active_url}`
›› **ᴀᴘɪ:** `{(active_api[:20] + '...') if active_api else 'ɴᴏᴛ ꜱᴇᴛ'}`
›› **ᴛᴜᴛᴏʀɪᴀʟ ʟɪɴᴋ:** `{active_tut}`
›› **ᴀᴘɪ ꜱᴛᴀᴛᴜꜱ:** {status}</blockquote>

**<u>ᴀʟʟ ꜱʜᴏʀᴛɴᴇʀꜱ ({len(shorteners)}):</u>**
<blockquote>{shorteners_display}</blockquote>

<blockquote>**≡ ᴜꜱᴇ ᴛʜᴇ ʙᴜᴛᴛᴏɴꜱ ʙᴇʟᴏᴡ ᴛᴏ ᴄᴏɴꜰɪɢᴜʀᴇ ʏᴏᴜʀ ꜱʜᴏʀᴛɴᴇʀꜱ!**</blockquote>"""

    reply_markup = InlineKeyboardMarkup([
        [InlineKeyboardButton(f'• {toggle_text} ꜱʜᴏʀᴛɴᴇʀ •', 'toggle_shortner'), InlineKeyboardButton('• ᴀᴅᴅ ꜱʜᴏʀᴛɴᴇʀ •', 'add_shortner')],
        [InlineKeyboardButton('• ꜱᴡɪᴛᴄʜ ꜱʜᴏʀᴛɴᴇʀ •', 'switch_shortner'), InlineKeyboardButton('• ʀᴇᴍᴏᴠᴇ ꜱʜᴏʀᴛɴᴇʀ •', 'rm_shortner')],
        [InlineKeyboardButton('• ꜱᴇᴛ ᴛᴜᴛᴏʀɪᴀʟ ʟɪɴᴋ •', 'set_tutorial_link'), InlineKeyboardButton('• ᴛᴇꜱᴛ ꜱʜᴏʀᴛɴᴇʀ •', 'test_shortner')],
        [InlineKeyboardButton('• 🔁 ᴀᴜᴛᴏ ᴍᴏᴅᴇ •', 'auto_shortner')],
        [InlineKeyboardButton('◂ ʙᴀᴄᴋ ᴛᴏ ꜱᴇᴛᴛɪɴɢꜱ', 'settings')] if hasattr(query_or_message, 'message') else []
    ])

    image_url = MESSAGES.get("SHORT", "https://telegra.ph/file/8aaf4df8c138c6685dcee-05d3b183d4978ec347.jpg")

    if hasattr(query_or_message, 'message'):
        await query_or_message.message.edit_media(
            media=InputMediaPhoto(media=image_url, caption=msg),
            reply_markup=reply_markup
        )
    else:
        await query_or_message.reply_photo(photo=image_url, caption=msg, reply_markup=reply_markup)


