@Client.on_callback_query(filters.regex("^add_shortner$"))
async def add_shortner(client: Client, query: CallbackQuery):
    if not query.from_user.id in client.admins:
        return await query.answer('❌ ᴏɴʟʏ ᴀᴅᴍɪɴꜱ ᴄᴀɴ ᴜꜱᴇ ᴛʜɪꜱ!', show_alert=True)

    await query.answer()

    msg = f"""<blockquote>**ᴀᴅᴅ / ᴇᴅɪᴛ ᴀ ꜱʜᴏʀᴛɴᴇʀ:**</blockquote>
**ᴄᴜʀʀᴇɴᴛ ꜱʜᴏʀᴛɴᴇʀꜱ:** `{len(getattr(client, 'shorteners', {}))}`

__<blockquote>**≡ ꜱᴇɴᴅ ᴛʜᴇ ɴᴇᴡ ꜱʜᴏʀᴛɴᴇʀ ɪɴ ᴛʜɪꜱ ꜰᴏʀᴍᴀᴛ ɪɴ ᴛʜᴇ ɴᴇxᴛ 90 ꜱᴇᴄᴏɴᴅꜱ!**</blockquote>__

**ꜰᴏʀᴍᴀᴛ:** `name url api tutorial_link`
**ᴇxᴀᴍᴘʟᴇ:** `gplinks gplinks.in 9435894656863495834957348 https://t.me/How_to_Download_7x/26`

**ɴᴏᴛᴇ:** ɴᴀᴍᴇ ᴍᴜꜱᴛ ʙᴇ ʟᴇᴛᴛᴇʀꜱ/ɴᴜᴍʙᴇʀꜱ ᴏɴʟʏ (ɴᴏ ꜱᴘᴀᴄᴇꜱ). ꜱᴇɴᴅɪɴɢ ᴀɴ ᴇxɪꜱᴛɪɴɢ ɴᴀᴍᴇ ᴡɪʟʟ ᴏᴠᴇʀᴡʀɪᴛᴇ ɪᴛ."""

    await query.message.edit_text(msg)
    try:
        res = await client.listen(user_id=query.from_user.id, filters=filters.text, timeout=90)
        response_text = res.text.strip()

        parts = response_text.split()
        if len(parts) == 4:
            name, raw_url, api, tutorial_link = parts
            name = name.lower()
            new_url = raw_url.replace('https://', '').replace('http://', '').replace('/', '')

            valid = (
                NAME_RE.match(name)
                and new_url and '.' in new_url
                and api and len(api) > 10
                and (tutorial_link.startswith('https://') or tutorial_link.startswith('http://'))
            )

            if valid:
                if not hasattr(client, 'shorteners'):
                    client.shorteners = {}
                client.shorteners[name] = {'url': new_url, 'api': api, 'tutorial_link': tutorial_link}

                # First shortner added automatically becomes active
                if not getattr(client, 'active_shortener', None):
                    client.active_shortener = name

                shortened_urls_cache.clear()
                await save_shorteners(client)

                await query.message.edit_text(
                    f"**✓ ꜱʜᴏʀᴛɴᴇʀ `{name}` ꜱᴀᴠᴇᴅ ꜱᴜᴄᴄᴇꜱꜱꜰᴜʟʟʏ!**\n\n**ᴜʀʟ:** `{new_url}`\n**ᴀᴄᴛɪᴠᴇ:** `{client.active_shortener}`",
                    reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('◂ ʙᴀᴄᴋ', 'shortner')]])
                )
            else:
                await query.message.edit_text("**✗ ɪɴᴠᴀʟɪᴅ ꜰᴏʀᴍᴀᴛ! ᴄʜᴇᴄᴋ ɴᴀᴍᴇ/ᴜʀʟ/ᴀᴘɪ/ᴛᴜᴛᴏʀɪᴀʟ ʟɪɴᴋ.**",
                                              reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('◂ ʙᴀᴄᴋ', 'shortner')]]))
        else:
            await query.message.edit_text("**✗ ɪɴᴠᴀʟɪᴅ ꜰᴏʀᴍᴀᴛ! ᴜꜱᴇ: `name url api tutorial_link`**",
                                          reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('◂ ʙᴀᴄᴋ', 'shortner')]]))
    except ListenerTimeout:
        await query.message.edit_text("**⏰ ᴛɪᴍᴇᴏᴜᴛ! ᴛʀʏ ᴀɢᴀɪɴ.**",
                                    reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('◂ ʙᴀᴄᴋ', 'shortner')]]))

