@Client.on_callback_query(filters.regex("^switch_shortner$"))
async def switch_shortner(client: Client, query: CallbackQuery):
    if not query.from_user.id in client.admins:
        return await query.answer('❌ ᴏɴʟʏ ᴀᴅᴍɪɴꜱ ᴄᴀɴ ᴜꜱᴇ ᴛʜɪꜱ!', show_alert=True)

    await query.answer()

    shorteners = getattr(client, 'shorteners', {}) or {}
    if not shorteners:
        return await query.message.edit_text("**✗ ɴᴏ ꜱʜᴏʀᴛɴᴇʀꜱ ᴀᴅᴅᴇᴅ ʏᴇᴛ! ᴀᴅᴅ ᴏɴᴇ ꜰɪʀꜱᴛ.**",
                                             reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('◂ ʙᴀᴄᴋ', 'shortner')]]))

    active_name = getattr(client, 'active_shortener', None)
    listing = "\n".join(f"{'✓' if n == active_name else '•'} `{n}`" for n in shorteners)
    msg = f"""<blockquote>**ꜱᴡɪᴛᴄʜ ᴀᴄᴛɪᴠᴇ ꜱʜᴏʀᴛɴᴇʀ:**</blockquote>
**ᴀᴠᴀɪʟᴀʙʟᴇ ꜱʜᴏʀᴛɴᴇʀꜱ:**
{listing}

__ꜱᴇɴᴅ ᴛʜᴇ ɴᴀᴍᴇ ᴏꜰ ᴛʜᴇ ꜱʜᴏʀᴛɴᴇʀ ᴛᴏ ᴀᴄᴛɪᴠᴀᴛᴇ ɪɴ ᴛʜᴇ ɴᴇxᴛ 60 ꜱᴇᴄᴏɴᴅꜱ!__"""

    await query.message.edit_text(msg)
    try:
        res = await client.listen(user_id=query.from_user.id, filters=filters.text, timeout=60)
        name = res.text.strip().lower()
        if name not in shorteners:
            return await query.message.edit_text(f"**✗ ꜱʜᴏʀᴛɴᴇʀ `{name}` ɴᴏᴛ ꜰᴏᴜɴᴅ!**",
                                                 reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('◂ ʙᴀᴄᴋ', 'shortner')]]))
        client.active_shortener = name
        await save_shorteners(client)
        await query.message.edit_text(f"**✓ ꜱᴡɪᴛᴄʜᴇᴅ ᴛᴏ ꜱʜᴏʀᴛɴᴇʀ `{name}`!**",
                                      reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('◂ ʙᴀᴄᴋ', 'shortner')]]))
    except ListenerTimeout:
        await query.message.edit_text("**⏰ ᴛɪᴍᴇᴏᴜᴛ! ᴛʀʏ ᴀɢᴀɪɴ.**",
                                    reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('◂ ʙᴀᴄᴋ', 'shortner')]]))

#===============================================================#

@Client.on_callback_query(filters.regex("^rm_shortner$"))
async def rm_shortner(client: Client, query: CallbackQuery):
    if not query.from_user.id in client.admins:
        return await query.answer('❌ ᴏɴʟʏ ᴀᴅᴍɪɴꜱ ᴄᴀɴ ᴜꜱᴇ ᴛʜɪꜱ!', show_alert=True)

    await query.answer()

    shorteners = getattr(client, 'shorteners', {}) or {}
    if not shorteners:
        return await query.message.edit_text("**✗ ɴᴏ ꜱʜᴏʀᴛɴᴇʀꜱ ᴛᴏ ʀᴇᴍᴏᴠᴇ!**",
                                             reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('◂ ʙᴀᴄᴋ', 'shortner')]]))

    active_name = getattr(client, 'active_shortener', None)
    listing = "\n".join(f"{'✓' if n == active_name else '•'} `{n}`" for n in shorteners)
    msg = f"""<blockquote>**ʀᴇᴍᴏᴠᴇ ꜱʜᴏʀᴛɴᴇʀ:**</blockquote>
**ᴀᴠᴀɪʟᴀʙʟᴇ ꜱʜᴏʀᴛɴᴇʀꜱ:**
{listing}

__ꜱᴇɴᴅ ᴛʜᴇ ɴᴀᴍᴇ ᴏꜰ ᴛʜᴇ ꜱʜᴏʀᴛɴᴇʀ ᴛᴏ ʀᴇᴍᴏᴠᴇ ɪɴ ᴛʜᴇ ɴᴇxᴛ 60 ꜱᴇᴄᴏɴᴅꜱ!__"""

    await query.message.edit_text(msg)
    try:
        res = await client.listen(user_id=query.from_user.id, filters=filters.text, timeout=60)
        name = res.text.strip().lower()
        if name not in shorteners:
            return await query.message.edit_text(f"**✗ ꜱʜᴏʀᴛɴᴇʀ `{name}` ɴᴏᴛ ꜰᴏᴜɴᴅ!**",
                                                 reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('◂ ʙᴀᴄᴋ', 'shortner')]]))
        del client.shorteners[name]

        if client.active_shortener == name:
            remaining = list(client.shorteners.keys())
            client.active_shortener = remaining[0] if remaining else None

        shortened_urls_cache.clear()
        await save_shorteners(client)
        await query.message.edit_text(f"**✓ ʀᴇᴍᴏᴠᴇᴅ ꜱʜᴏʀᴛɴᴇʀ `{name}`!**\n**ᴀᴄᴛɪᴠᴇ ɴᴏᴡ:** `{client.active_shortener or 'ɴᴏɴᴇ'}`",
                                      reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('◂ ʙᴀᴄᴋ', 'shortner')]]))
    except ListenerTimeout:
        await query.message.edit_text("**⏰ ᴛɪᴍᴇᴏᴜᴛ! ᴛʀʏ ᴀɢᴀɪɴ.**",
                                    reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton('◂ ʙᴀᴄᴋ', 'shortner')]]))

